    return value is None or value == ""


def _numeric_value(value: Any) -> Decimal:
    if _is_empty(value):
        return Decimal("0")
    if isinstance(value, bool):
        return Decimal(int(value))
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal("0")


