    transitions = (
        ("P", "Q", "qualify", _amt_positive, (("set", "STAGE_PCT", "25"), ("audit", "OPP_QUAL"))),
        ("Q", "N", "advance", None, (("set", "STAGE_PCT", "60"),)),
        ("N", "W", "close_won", _close_date_present,
         (("set", "STAGE_PCT", "100"), ("audit", "OPP_WON"), ("notify", "won_deal"))),
        ("P", "L", "close_lost", _lost_reason_present,
         (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
        ("Q", "L", "close_lost", _lost_reason_present,
         (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
        ("N", "L", "close_lost", _lost_reason_present,
         (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
    )

    for from_state, to_state, transition_event, guard, actions in transitions:
        if state != from_state or event != transition_event:
            continue
        if guard is not None and not guard(record):
            continue

        result_record = dict(record)
        audits: list[str] = []
        notifies: list[str] = []

        for action in actions:
            kind = action[0]
            if kind == "set":
                result_record[action[1]] = action[2]
            elif kind == "audit":
                audits.append(action[1])
            elif kind == "notify":
                notifies.append(action[1])

        return {
            "state": to_state,
            "record": result_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": dict(record),
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
